INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1000, "vo_minigame_1013_icon_1_002_001", 2, 1, "vo_minigame_1013_icon_2_002_001", "訓練はまだ\nここからですわ", 2, 3000, "調子が上がって\nきたなっ", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5000, "vo_minigame_1013_icon_1_003_001", 2, 2, "vo_minigame_1013_icon_2_003_001", "クスクス、悪くない\n流れですわね", 2, 3000, "ほらほら、\nまだいけるだろ？", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_1_004_001", 2, 3, "vo_minigame_1013_icon_2_004_001", "すばらしい\n記録ですわ", 3, 3000, "へへっ、おまえら\nやるじゃねえか！", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_1_005_001", 2, 4, "vo_minigame_1013_icon_2_005_001", "乗りに乗って\nいますわね", 3, 3000, "あたしたちはまだ\n止まらねえぜ！", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_1_005_002", 2, 5, "vo_minigame_1013_icon_2_005_002", "まだまだ行きます\nついてきなさい", 3, 3000, "見てろよ！\nマコト班の快進撃だ！", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10000, "vo_minigame_1013_icon_1_005_003", 2, 6, "vo_minigame_1013_icon_2_005_003", "エリコ班の\n本領発揮ですわ！", 3, 3000, "うおぉぉっ！\n絶好調だぜ！", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_1_006_001", 2, 7, "vo_minigame_1013_icon_2_006_001", "ここからは\n前人未到の領域です！", 3, 3000, "どこまで行けるか\n楽しみだなっ！", 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_1_007_001", 3, 8, "vo_minigame_1013_icon_2_007_001", "厄介でしたわ…", 4, 1000, "まだ諦めんなよっ", 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_1_007_002", 3, 9, "vo_minigame_1013_icon_2_007_002", "油断大敵です", 4, 1000, "冷やっとしたぜ…！", 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, "vo_minigame_1013_icon_1_007_003", 3, 10, "vo_minigame_1013_icon_2_007_003", "忌々しいっ…", 4, 1000, "弱音を吐くなっ", 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (99, "vo_minigame_1013_icon_1_008_001", 4, 11, "vo_minigame_1013_icon_2_008_001", "大所帯ですわね", 3, 1500, "マコト班集合！", 6);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (99, "vo_minigame_1013_icon_1_008_002", 4, 12, "vo_minigame_1013_icon_2_008_002", "エリコ班へようこそ", 3, 1500, "連携してくぞ！", 6);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_1_020_001", 1, 13, "vo_minigame_1013_icon_2_020_001", "ナナカちゃんに\nお任せあれ", 6, 3000, "みんなに力を！", 8);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_1_022_001", 1, 14, "vo_minigame_1013_icon_2_022_001", "はっはっは！\n任せろ！", 7, 3000, "任せてくれたまえ", 9);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (0, "vo_minigame_1013_icon_1_023_001", 1, 15, "vo_minigame_1013_icon_2_023_001", "どんどんいくわよ", 8, 3000, "ほな、いきまひょか", 10);
